import SwiftUI
import UIKit

// Pro looks that live where people actually are — the home screen, the calendar, the editor —
// rather than in the flock sheet, which few free users ever open. Decoration only: none of
// these change what can be written, kept, or found.

/// Alternate home-screen icons. Art is generated by `tools/appicons/make_icons.py` from the
/// costume SVGs; each name must also be listed in `ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES`.
enum AppIconChoice: String, CaseIterable, Identifiable {
    case classic
    case night
    // Raw values match `SheepCostume` so the name comes from the same string.
    case santaHat, flowerCrown, strawHat, beret, beanie, sunglasses, headphones

    var id: String { rawValue }

    private var assetSuffix: String {
        self == .classic ? "Default" : rawValue.prefix(1).uppercased() + rawValue.dropFirst()
    }

    /// What `setAlternateIconName` takes; `nil` is the primary icon.
    var iconName: String? { self == .classic ? nil : "AppIcon-" + assetSuffix }

    /// An app icon set can't be loaded with `Image(_:)`, so each has a small imageset copy.
    var previewAsset: String { "iconPreview_" + assetSuffix }

    var localizedNameKey: String {
        switch self {
        case .classic: return "#iconClassic"
        case .night: return "#pastureNight"
        default: return SheepCostume(rawValue: rawValue)?.localizedNameKey ?? "#iconClassic"
        }
    }

    static var current: AppIconChoice {
        let name = UIApplication.shared.alternateIconName
        return allCases.first { $0.iconName == name } ?? .classic
    }
}

/// The editor's paper. Each theme carries its own light and dark colours, except midnight,
/// which is dark in both and so forces the editor's colour scheme.
enum PaperTheme: String, CaseIterable, Identifiable {
    case plain, dots, grid, kraft, letter, midnight

    enum Pattern { case none, dots, grid, margin }

    var id: String { rawValue }

    var localizedNameKey: String {
        switch self {
        case .plain: return "#paperPlain"
        case .dots: return "#paperDots"
        case .grid: return "#paperGrid"
        case .kraft: return "#paperKraft"
        case .letter: return "#paperLetter"
        case .midnight: return "#paperMidnight"
        }
    }

    var paper: Color {
        switch self {
        case .plain, .dots, .grid: return .surface
        case .kraft: return Self.adaptive(light: 0xE8DAC0, dark: 0x3A3127)
        case .letter: return Self.adaptive(light: 0xFBF5E6, dark: 0x2B2822)
        case .midnight: return Color(hex: 0x1C2340)
        }
    }

    /// Text colour. The plain papers keep `.textPrimary`.
    var ink: Color {
        switch self {
        case .plain, .dots, .grid: return .textPrimary
        case .kraft: return Self.adaptive(light: 0x4A3A28, dark: 0xEBDDC4)
        case .letter: return Self.adaptive(light: 0x3A342B, dark: 0xEDE5D3)
        case .midnight: return Color(hex: 0xE6E4F2)
        }
    }

    var pattern: Pattern {
        switch self {
        case .plain, .kraft: return .none
        case .dots, .midnight: return .dots
        case .grid: return .grid
        case .letter: return .margin
        }
    }

    var patternColor: Color {
        switch self {
        case .grid: return Color.accent.opacity(0.14)
        case .letter: return Color(hex: 0xD9776A).opacity(0.45)
        case .midnight: return Color.white.opacity(0.16)
        default: return Color.textSecondary.opacity(0.28)
        }
    }

    /// Kraft and letter write in New York; the rest keep Roboto like the rest of the app.
    func font(size: CGFloat) -> Font {
        switch self {
        case .kraft, .letter: return .system(size: size + 1, design: .serif)
        default: return .custom(AppFonts.regular, size: size)
        }
    }

    var forcedColorScheme: ColorScheme? { self == .midnight ? .dark : nil }

    private static func adaptive(light: UInt32, dark: UInt32) -> Color {
        Color(UIColor { $0.userInterfaceStyle == .dark ? UIColor(hex: dark) : UIColor(hex: light) })
    }
}

/// The paper itself: fill plus pattern. Drawn, not an image, so it is sharp at any size
/// and costs nothing in the bundle.
struct PaperBackground: View {
    let theme: PaperTheme

    var body: some View {
        theme.paper
            .overlay {
                Canvas { context, size in
                    let color = GraphicsContext.Shading.color(theme.patternColor)
                    let step: CGFloat = 22
                    switch theme.pattern {
                    case .none:
                        break
                    case .dots:
                        for x in stride(from: step / 2, to: size.width, by: step) {
                            for y in stride(from: step / 2, to: size.height, by: step) {
                                context.fill(Path(ellipseIn: CGRect(x: x - 1, y: y - 1, width: 2, height: 2)), with: color)
                            }
                        }
                    case .grid:
                        var path = Path()
                        for x in stride(from: 0, to: size.width, by: step) {
                            path.move(to: CGPoint(x: x, y: 0)); path.addLine(to: CGPoint(x: x, y: size.height))
                        }
                        for y in stride(from: 0, to: size.height, by: step) {
                            path.move(to: CGPoint(x: 0, y: y)); path.addLine(to: CGPoint(x: size.width, y: y))
                        }
                        context.stroke(path, with: color, lineWidth: 0.5)
                    case .margin:
                        var path = Path()
                        path.move(to: CGPoint(x: 12, y: 0)); path.addLine(to: CGPoint(x: 12, y: size.height))
                        context.stroke(path, with: color, lineWidth: 1)
                    }
                }
            }
    }
}

private extension UIColor {
    convenience init(hex: UInt32) {
        self.init(red: CGFloat((hex >> 16) & 0xFF) / 255,
                  green: CGFloat((hex >> 8) & 0xFF) / 255,
                  blue: CGFloat(hex & 0xFF) / 255,
                  alpha: 1)
    }
}

private extension Color {
    init(hex: UInt32) { self.init(UIColor(hex: hex)) }
}

/// A mood sheep wearing the Dress Up costume. App-only: `SheepMoodIcon` is shared with the
/// widget, which knows nothing about costumes or Pro.
struct DressedMoodSheep: View {
    let mood: String
    var size: CGFloat = 36
    /// `nil` wears whatever the user picked (Pro only); pass one to preview it.
    var costume: SheepCostume? = nil

    @ObservedObject private var synced = SyncedSettings.shared
    @AppStorage("isPro") private var isPro = false

    private var worn: SheepCostume {
        costume ?? (isPro ? synced.moodSheepCostume : .none)
    }

    var body: some View {
        SheepMoodIcon(mood: mood, size: size)
            .overlay {
                if let placement = worn.headPlacement {
                    Image(placement.asset)
                        .resizable()
                        .aspectRatio(contentMode: .fit)
                        .frame(width: size * placement.widthFactor)
                        .offset(x: size * placement.x, y: size * placement.y)
                        .allowsHitTesting(false)
                }
            }
    }
}
